I'm having some trouble with this spatial capture-recapture model in NIMBLE. My base model works but I'm trying to add a "zeros trick" so that the augmented individuals that were never caught don't go into the pmf to speed up the model. When I run it RStudio aborts so I don't have the error messages. I wanted to check if there was something obviously stupid I'm doing. I don't have a reproducible example but if it's not obvious then I can work on creating one.

My observed mark-recapture data are y[i,j,k,g] for individual i at trap j on day k within site g. M is my max population size including the augment. n0 is a vector of the number of individuals with capture histories at each site.

There are certainly other improvements to be made, but I was just trying to get this working at this point. Any suggestions would be appreciated if they are obvious. I'm wondering if it's the use of the prod() function with the indexing but I'm not sure how to adjust that since n0 and M change by site.

scr_zeros <- nimbleCode( {

  alpha2 ~ dnorm(0, pow(1.5, -3)) # Trap behavior universal distribution across sites
  mu_0 ~ dnorm(0, pow(1.5, -2))
  sd_0 ~ dunif(0, 3)
  mu_1 ~ dnorm(0, pow(1.5, -2))
  sd_1 ~ dunif(0, 3)
  alpha_1_sex ~ dnorm(0, pow(1.5, -2))
  beta_0 ~ dnorm(0, pow(3, -2))
  beta_1 ~ dnorm(0, pow(3, -2))
  beta_2 ~ dnorm(0, pow(3, -2))

  for(g in 1:n_sites) {
    psi[g] ~ dbeta(1, 1) # prob of individual being in the population
    psi.sex[g] ~ dbeta(1, 1)
    alpha_1_int[g] ~ dnorm(mu_1, pow(sd_1, -2))

    for(t in 1:2) {
      sigma[g, t] <- pow(1 / (2*alpha1[g, t]), 0.5) # sd of half normal
      log(alpha1[g, t]) <- alpha_1_int[g] + alpha_1_sex * (t-1) # affect of being female on home range
    }

    for(k in 1:K) {
      alpha0[g, k] ~ dnorm(mu_0, sd_0)
    }

    for(i in 1:M[g]) {
      Sex[g, i] ~ dbern(psi.sex[g])
      Sex2[g, i] <- Sex[g, i] + 1
      z[g, i] ~ dbern(psi[g])
      s[g, i] ~ dunif(xlim[g, 1], xlim[g, 2])

      for(j in 1:max_trap[g]) {
        d[g,i,j] <- abs(s[g, i] - trap_locs[g, j])

        for(k in 1:K) {
          p[g, i, j, k] <- p0[g, i, j, k] * exp(-1 * alpha1[g, Sex2[g, i]] * d[g, i, j] * d[g, i, j])
        } # k
      } # j
    } # i

  for(i in 1:n0[g]) {
    for(j in 1:max_trap[g]) {
      for(k in 1:K) {
        y[i, j, k, g] ~ dbern(p[g, i, j, k])
        logit(p0[g, i, j, k]) <- alpha0[g, k] + (alpha2 * C[i, k, g])
      }
    }
  }

  for(i in (n0[g] + 1):M[g]) {
    for(k in 1:K) {
    logit(p0[g, i, 1:max_trap[g], k]) <- alpha0[g, k]
      } # k
    zeros[i, g] ~ dbern(1 - prod(p[i, g, 1:max_trap[g], 1:K] * z[g, i]))
  } # i

    # Derived parameters
    N[g] <- sum(z[g , 1:M[g]])
    density[g] <- sum(z[g , 1:M[g]]) / (xlim[g, 2] - xlim[g, 1]) # divided distances by 100 so calculates turtles per 100 m of canal

    site_zeros[g] ~ dnorm(density[g] - (beta_0 + beta_1 * forest[g] + beta_2 * depth[g]), pow(3, -2))
  } # g

})

I'm using default everything and running the model via

samples <- nimbleMCMC(
  code = scr_zeros,
  constants = jags_data_site, ## provide the combined data & constants as constants
  inits = initsf,
  monitors = parameters,
  niter = 100,
  nburnin = 1,
  thin = 1,
  nchains = 1)

Thanks,
Dan

